<script>
 import {onMount,tick} from 'svelte';
 import WindowControls from './WindowControls.svelte';
 import {screenSharingWindow,screenSharingPeer,screenSharingReceiver,screenSharingCapabilities,screenSharingPolicy,SCREEN_SHARING_RECEIVERS} from './screen-sharing-state.js';
 import {screenSharingMenus} from './screen-sharing-menus.js';
 import {screenSharingHitTest,screenSharingTextFile} from './screen-sharing-render.js';
 import {createScreenSharingNativeView} from './screen-sharing-native-view.js';
 import './screen-sharing.css';
 let {window,state: screenSharingState,profile,windowId=window?.id,preferences,localSession,getFile,execute,registerView,available=true,active=true,controls={}}=$props();
 let root=$state(null),canvas=$state(null),message=$state(''),username=$state(''),passcode=$state(''),remember=$state(false),hostname=$state(''),groupName=$state(''),administratorId=$state(''),administratorPasscode=$state('');
 let originalState,originalProfile,originalWindow,originalId,retired=false,facade,drag=null;
 const session=$derived(screenSharingWindow(screenSharingState,windowId)),cap=$derived(screenSharingCapabilities(profile)),peer=$derived(screenSharingPeer(screenSharingState,session?.peerId)),receiver=$derived(screenSharingReceiver(session?.peerId)),access=$derived(screenSharingPolicy(preferences,localSession));
 const connected=$derived(session?.phase==='connected'&&access.enabled&&access.allowed&&session.sceneUserId===access.userId),canControl=$derived(connected&&session.mode==='control'),remoteWindow=$derived(peer?.desktop.windows.find(row=>row.id===peer.desktop.activeWindowId&&row.display===session?.display)),remoteFile=$derived(peer?.files.find(row=>row.id===remoteWindow?.fileId)),selected=$derived(peer?.files.find(row=>row.id===session?.selectedFileId));
 const groups=$derived(screenSharingState.groups),visibleReceivers=$derived(SCREEN_SHARING_RECEIVERS.filter(row=>session?.sidebar==='network'||session?.sidebar==='all'&&screenSharingState.connections.some(saved=>saved.peerId===row.id)||screenSharingState.connections.some(saved=>saved.peerId===row.id&&saved.groupIds.includes(session?.sidebar))));
 const administrators=$derived(localSession?.users.filter(row=>row.kind==='local'&&preferences?.configuration.users.administratorIds.includes(row.id))??[]),menus=$derived(screenSharingMenus({state: screenSharingState,profile,windowId,preferences,localSession})),menu=$derived(menus.find(row=>row.id===session?.menu)),resultFile=$derived(session?.resultFileId?getFile?.(session.resultFileId):null);
 function current(){return !retired&&root?.isConnected&&screenSharingState===originalState&&profile===originalProfile&&window===originalWindow&&windowId===originalId;}
 async function command(suffix,payload={}){if(!current()||!available||!active)return;const response=await execute(`screensharing.${suffix}`,{windowId},payload);if(current())message=response?.status==='applied'?'':response?.error?.message??'This local Screen Sharing operation is unavailable.';return response;}
 async function menuAction(item){if(!item.enabled||!item.request||!current())return;const response=await execute(item.request.command,item.request.target,item.request.payload);if(current()){message=response?.status==='applied'?'':response?.error?.message??'The original menu operation is unavailable.';if(response?.status==='applied'&&session?.menu)command('sheet',{menu:null});}}
 async function start(id){username='';passcode='';remember=false;const selected=await command('select',{peerId:id});if(current()&&selected?.status==='applied')await command('connect');}
 async function signIn(){const secret=passcode;passcode='';await command('authenticate',{username,passcode:secret,remember});}
 async function authorize(){const secret=administratorPasscode;administratorPasscode='';await command('policy',{administratorId:administratorId||administrators[0]?.id,passcode:secret});}
 function position(event){const bounds=canvas?.getBoundingClientRect();return bounds?{x:Math.max(0,Math.min(1024,Math.round((event.clientX-bounds.left)/bounds.width*1024))),y:Math.max(0,Math.min(640,Math.round((event.clientY-bounds.top)/bounds.height*640)))}:null;}
 function pointerDown(event){if(!canControl||!peer||!current())return;const point=position(event);if(!point)return;const hit=screenSharingHitTest(peer,session,point.x,point.y);if(hit.kind==='title'){const row=peer.desktop.windows.find(w=>w.id===hit.remoteWindowId);drag={id:row.id,startX:point.x,startY:point.y,x:row.x,y:row.y};event.currentTarget.setPointerCapture(event.pointerId);}}
 function pointerUp(event){if(!canControl||!current()){drag=null;return;}const point=position(event);if(!point)return;const move=drag;drag=null;if(move&&Math.abs(point.x-move.startX)+Math.abs(point.y-move.startY)>4)command('remote.move',{remoteWindowId:move.id,x:Math.max(0,Math.min(700,move.x+point.x-move.startX)),y:Math.max(26,Math.min(420,move.y+point.y-move.startY))});else command('pointer',{...point,action:'click'});}
 function doubleClick(event){if(!canControl)return;const point=position(event);if(point)command('pointer',{...point,action:'doubleClick'});}
 function dropLocal(event){event.preventDefault();if(!canControl)return;const id=event.dataTransfer?.getData('application/x-jesteros-file-id');if(id){command('upload',{fileId:id});return;}const many=event.dataTransfer?.getData('application/x-jesteros-file-ids');try{const ids=JSON.parse(many||'null');if(Array.isArray(ids)&&ids.length===1&&typeof ids[0]==='string'){command('upload',{fileId:ids[0]});return;}}catch{}message='Drop exactly one canonical local File. Host files and external transport are not accepted.';}
 function dragPeer(event,file){event.dataTransfer.setData('application/x-jesteros-authored-peer-file',JSON.stringify({peerId:peer.id,fileId:file.id}));event.dataTransfer.effectAllowed='copy';}
 function receiveDrop(event){event.preventDefault();try{const row=JSON.parse(event.dataTransfer?.getData('application/x-jesteros-authored-peer-file')||'null');if(row?.peerId===peer?.id&&peer.files.some(file=>file.id===row.fileId)){command('download',{fileId:row.fileId});return;}}catch{}message='Drop a document from this authored receiver realm.';}
 function keyboard(event){if(event.key==='Escape'){event.preventDefault();if(session?.phase==='authentication')command('cancel');else command('sheet',{sheet:null,menu:null});}const modifier=cap.windows?event.ctrlKey:event.metaKey;if(modifier&&event.key.toLowerCase()==='n'){event.preventDefault();command('window.new',session?.peerId?{peerId:session.peerId}:{});}if(modifier&&event.key.toLowerCase()==='s'&&canControl&&remoteWindow){event.preventDefault();command('remote.save',{remoteWindowId:remoteWindow.id});}}
 $effect(()=>{JSON.stringify(peer);JSON.stringify(session);access.enabled;access.allowed;connected;if(facade&&current()&&connected)facade.render(screenSharingState.sceneTime);});
 onMount(()=>{originalState=screenSharingState;originalProfile=profile;originalWindow=window;originalId=windowId;facade=createScreenSharingNativeView({getRoot:()=>root,getCanvas:()=>canvas,getState:()=>screenSharingState,getProfile:()=>profile,getWindow:()=>window,windowId,getPreferences:()=>preferences,getLocalSession:()=>localSession,available:()=>current()&&available&&active,tick});registerView?.(windowId,facade);facade.render();const observer=typeof ResizeObserver==='function'?new ResizeObserver(()=>{if(current()&&connected)facade.render(screenSharingState.sceneTime);}):null;observer?.observe(root);return()=>{retired=true;passcode='';administratorPasscode='';username='';drag=null;observer?.disconnect();facade.destroy();registerView?.(originalId,null,facade);};});
</script>

<section bind:this={root} class="screen-sharing-app" class:classic={cap.classic} class:golden={cap.golden} class:windows={cap.windows} data-screen-sharing-window-id={windowId} data-profile={typeof profile==='string'?profile:profile.id} role="region" aria-label={cap.label} tabindex="0" onkeydown={keyboard}>
 {#if session}
 <header class="screen-sharing-titlebar">{#if !cap.windows}<WindowControls active={active} onclose={()=>command('window.close')} onminimize={controls.onminimize} onzoom={controls.onzoom} onfullscreen={controls.onfullscreen} fullScreen={controls.fullScreen} zoomed={controls.zoomed}/>{/if}<strong>{connected?receiver.name:cap.label}</strong><span>{connected?'Authored local session':'Connections'}</span></header>
 {#if cap.windows}<nav class="screen-sharing-menubar" aria-label="Remote desktop menus">{#each menus as group}<button data-screen-sharing-control={`menu:${group.id}`} aria-expanded={session.menu===group.id} disabled={!available||!active} onclick={()=>command('sheet',{menu:session.menu===group.id?null:group.id})}>{group.label}</button>{/each}</nav>{/if}
 {#if menu}<div class="screen-sharing-menu" role="menu" aria-label={menu.label}>{#each menu.children as item}<button data-screen-sharing-control={`menu-item:${item.id}`} role="menuitem" disabled={!item.enabled} onclick={()=>menuAction(item)}><span>{item.checked?'✓ ':''}{item.label}</span><kbd>{item.shortcut??''}</kbd></button>{/each}</div>{/if}
 <div class="screen-sharing-disclosure"><span class="screen-sharing-local-dot"></span><span>LOCAL AUTHORED RECEIVERS · NO NETWORK OR HOST DESKTOP</span><button data-screen-sharing-control="help" onclick={()=>command('sheet',{sheet:'help'})}>ⓘ</button></div>
 <div class="screen-sharing-interior" inert={!available||!active||!!session.sheet||session.phase==='authentication'}>
 {#if connected}
 <div class="screen-sharing-session-toolbar" role="toolbar" aria-label="Screen sharing controls"><button data-screen-sharing-control="connections" onclick={()=>command('disconnect')}>‹ Connections</button><div class="screen-sharing-toolbar-divider"></div><label>Mode <select data-screen-sharing-control="mode" value={session.mode} onchange={event=>command('settings',{mode:event.currentTarget.value})}><option value="control">Control</option><option value="observe">Observe</option></select></label><button data-screen-sharing-control="scale" class:selected={session.scale==='fit'} onclick={()=>command('settings',{scale:session.scale==='fit'?'actual':'fit'})} title="Scale to fit available space">↔ Fit</button><label>Quality <select data-screen-sharing-control="quality" disabled={session.connectionType!=='standard'} value={session.connectionType==='high-performance'?'full':session.quality} onchange={event=>command('settings',{quality:event.currentTarget.value})}><option value="adaptive">Adaptive</option><option value="full">Full</option></select></label>{#if session.displays===2}<label>Display <select data-screen-sharing-control="display" value={session.display} onchange={event=>command('settings',{display:Number(event.currentTarget.value)})}><option value="0">1</option><option value="1">2</option></select></label>{/if}<button data-screen-sharing-control="settings" onclick={()=>command('sheet',{sheet:'settings'})}>⚙</button><button data-screen-sharing-control="capture" onclick={()=>command('capture')}>Save Capture</button></div>
 <div class="screen-sharing-session-body">
 <div class="screen-sharing-desktop-viewport" data-screen-sharing-area="content" ondragover={event=>event.preventDefault()} ondrop={dropLocal} role="region" aria-label="Rendered authored virtual desktop" tabindex="0">
 <canvas bind:this={canvas} class="screen-sharing-desktop-canvas" style:width={session.dynamicResolution?'100%':session.scale==='fit'?`${session.zoom}%`:`${1024*session.zoom/100}px`} style:height={session.dynamicResolution?'100%':'auto'} data-screen-sharing-canvas data-screen-sharing-control="desktop" width="1024" height="640" aria-label={`${receiver.name} authored desktop. Double-click a file to open; drag a window title to move. No host input.`} role="img" tabindex="0" onpointerdown={pointerDown} onpointerup={pointerUp} onpointercancel={()=>{drag=null;}} ondblclick={doubleClick} onkeydown={event=>{if(event.key==='Enter'&&selected&&canControl){event.preventDefault();command('remote.open',{fileId:selected.id});}}}></canvas>
 {#if session.mode==='observe'}<div class="screen-sharing-observe-badge">Observe only</div>{/if}
 </div>
 <aside class="screen-sharing-peer-files" aria-label="Actual authored receiver files"><header><strong>{receiver.name}</strong><small>Distinct peer realm</small></header><div class="screen-sharing-peer-file-list">{#each peer.files as file}<div class:selected={session.selectedFileId===file.id} class="screen-sharing-peer-file"><button data-screen-sharing-control={`peer-file:${file.id}`} onclick={()=>command('remote.select',{fileId:file.id})} ondblclick={()=>canControl&&command('remote.open',{fileId:file.id})} draggable="true" ondragstart={event=>dragPeer(event,file)}><span class="screen-sharing-document-icon">▤</span><span>{file.name}<small>{file.mime} · rev {file.revision}</small></span></button><button aria-label={`Open ${file.name}`} data-screen-sharing-control={`open:${file.id}`} disabled={!canControl} onclick={()=>command('remote.open',{fileId:file.id})}>↗</button></div>{/each}</div><button data-screen-sharing-control="remote:new" disabled={!canControl} onclick={()=>command('remote.new')}>＋ New Text File</button><button data-screen-sharing-control="upload" disabled={!canControl} onclick={()=>command('upload')}>Send Local File…</button><button data-screen-sharing-control="download" disabled={!selected} onclick={()=>command('download')}>Receive Selected File</button><p>Drag a canonical local File onto the desktop to send its real bytes. Drag a peer document to the receiving tray below.</p></aside>
 </div>
 {#if remoteWindow}<section class="screen-sharing-editor" aria-label="Accessible actual peer document editor"><header><strong>{remoteFile.name}{remoteWindow.dirty?' — Edited':''}</strong><small>{screenSharingTextFile(remoteFile)?'Actual draft rendered above':'Binary document properties'}</small><button data-screen-sharing-control="remote:save" disabled={!canControl||!remoteWindow.dirty} onclick={()=>command('remote.save',{remoteWindowId:remoteWindow.id})}>Save on Peer</button><button data-screen-sharing-control="remote:close" disabled={!canControl} onclick={()=>command('remote.close',{remoteWindowId:remoteWindow.id})}>Close</button></header>{#if screenSharingTextFile(remoteFile)}<textarea data-screen-sharing-control="remote:editor" aria-label={`Edit actual ${remoteFile.name} on authored receiver`} readonly={!canControl} maxlength="65536" value={remoteWindow.draft} oninput={event=>command('remote.edit',{remoteWindowId:remoteWindow.id,text:event.currentTarget.value})}></textarea>{:else}<p>{remoteFile.mime} · {remoteFile.content.length} retained content units. Receive to local Files to open genuine bytes in a compatible viewer.</p>{/if}</section>{/if}
 <footer class="screen-sharing-transfer-tray" role="region" aria-label="Receive peer files into canonical Files" ondragover={event=>event.preventDefault()} ondrop={receiveDrop}><span>↓ Receive actual bytes to</span><select data-screen-sharing-control="destination" aria-label="Canonical receiving folder" value={session.destination} onchange={event=>command('settings',{destination:event.currentTarget.value})}><option value="downloads">Downloads</option><option value="documents">Documents</option><option value="desktop">Desktop</option></select><label><input data-screen-sharing-control="clipboard" type="checkbox" checked={session.sharedClipboard} onchange={event=>command('settings',{sharedClipboard:event.currentTarget.checked})}/> Use Shared Clipboard</label><button data-screen-sharing-control="clipboard:send" disabled={!canControl||!session.sharedClipboard||!remoteWindow} onclick={()=>command('clipboard.send')}>Send Clipboard</button><button data-screen-sharing-control="clipboard:receive" disabled={!session.sharedClipboard||!remoteWindow} onclick={()=>command('clipboard.receive')}>Get Clipboard</button><button data-screen-sharing-control="cancel" onclick={()=>command('cancel')}>Disconnect / Cancel</button></footer>
 {:else}
 <div class="screen-sharing-connections">
 <aside class="screen-sharing-sidebar"><h2>{cap.classic?'Shared Computers':'Connections'}</h2><button data-screen-sharing-control="sidebar:all" class:selected={session.sidebar==='all'} onclick={()=>command('sidebar',{id:'all'})}><span>▦</span> All Connections <small>{screenSharingState.connections.length}</small></button><button data-screen-sharing-control="sidebar:network" class:selected={session.sidebar==='network'} onclick={()=>command('sidebar',{id:'network'})}><span>◎</span> {cap.windows?'Local receivers':'Network'} <small>{screenSharingState.peers.length}</small></button><h3>Groups</h3>{#each groups as group}<button data-screen-sharing-control={`group:${group.id}`} class:selected={session.sidebar===group.id} onclick={()=>command('sidebar',{id:group.id})}>▱ {group.name}</button>{/each}<div class="screen-sharing-group-tools"><input data-screen-sharing-control="group:name" aria-label="Connection group name" maxlength="64" placeholder="Group name" bind:value={groupName}/><button data-screen-sharing-control="group:add" disabled={!groupName.trim()} onclick={()=>command('group.add',{name:groupName})}>＋</button>{#if !['network','all'].includes(session.sidebar)}<button data-screen-sharing-control="group:rename" disabled={!groupName.trim()} onclick={()=>command('group.rename',{groupId:session.sidebar,name:groupName})}>Rename</button><button data-screen-sharing-control="group:delete" onclick={()=>command('group.delete',{groupId:session.sidebar})}>−</button>{/if}</div><p>Saved connections contain receiver identity only. Authentication stays in live app memory.</p></aside>
 <main class="screen-sharing-receivers" data-screen-sharing-area="content"><header><div><h1>{session.sidebar==='network'?(cap.windows?'Choose a local desktop':'Network'):session.sidebar==='all'?'All Connections':groups.find(row=>row.id===session.sidebar)?.name}</h1><p>{cap.classic?'Connect using an authored computer name or vnc:// name.':'Choose a computer to view its authored virtual desktop.'}</p></div><button data-screen-sharing-control="connection:new" aria-label="New Connection" onclick={()=>command('sheet',{sheet:'connection'})}>＋</button><button data-screen-sharing-control="connection:settings" aria-label={cap.settingsLabel} onclick={()=>command('sheet',{sheet:'settings'})}>⚙</button></header>
 {#if !access.valid||!access.enabled||!access.allowed}<section class="screen-sharing-policy" role="status"><strong>{access.remoteManagement?'Remote Management is enabled':!access.enabled?'Screen Sharing is Off':'Active user has no screen-sharing permission'}</strong><p>The local receiver lab uses the exact canonical Sharing service and allowed-user list. An actual scene administrator must authorize access; no independent policy is stored here.</p><button data-screen-sharing-control="policy:open" onclick={()=>command('sheet',{sheet:'settings'})}>Authorize Sharing…</button></section>{/if}
 <div class="screen-sharing-receiver-grid">{#each visibleReceivers as row}<article class:selected={session.peerId===row.id} class="screen-sharing-receiver"><button class="screen-sharing-receiver-select" data-screen-sharing-control={`receiver:${row.id}`} onclick={()=>command('select',{peerId:row.id})}><svg viewBox="0 0 120 96" role="img" aria-label="Authored receiver computer"><rect x="9" y="8" width="102" height="65" rx="5" fill="#92999f"/><rect x="13" y="12" width="94" height="55" rx="2" fill={row.accent}/><path d="M14 57C38 25 59 60 105 30V66H14Z" fill="#244849"/><path d="M51 74h18l4 12H47z" fill="#c0c4c7"/><path d="M36 88h48" stroke="#9da5aa" stroke-width="5" stroke-linecap="round"/></svg><h2>{row.name}</h2><p>{row.hostname}</p><small>Authored local receiver · {row.highPerformance&&cap.highPerformance?'Virtual displays available':'Standard desktop'}</small></button><button class="primary" data-screen-sharing-control={`connect:${row.id}`} disabled={!access.enabled||!access.allowed} onclick={()=>start(row.id)}>Connect</button>{#if screenSharingState.connections.some(saved=>saved.peerId===row.id)}<small class="screen-sharing-saved">Saved connection</small>{/if}</article>{/each}</div>
 {#if visibleReceivers.length===0}<div class="screen-sharing-empty"><h2>No saved connections</h2><p>Connect to one of the two functional authored receivers in {cap.windows?'Local receivers':'Network'} to save its identity.</p></div>{/if}
 {#if session.peerId&&screenSharingState.connections.some(saved=>saved.peerId===session.peerId)}<div class="screen-sharing-connection-actions"><strong>{receiver.name}</strong><select data-screen-sharing-control="connection:group" aria-label="Add selected connection to group" value="" onchange={event=>event.currentTarget.value&&command('connection.group',{groupId:event.currentTarget.value,member:true})}><option value="">Add to Group…</option>{#each groups as group}<option value={group.id}>{group.name}</option>{/each}</select>{#if !['all','network'].includes(session.sidebar)}<button data-screen-sharing-control="connection:remove-group" onclick={()=>command('connection.group',{groupId:session.sidebar,member:false})}>Remove from Group</button>{/if}<button data-screen-sharing-control="connection:delete" onclick={()=>command('connection.delete')}>Delete Saved Connection</button></div>{/if}
 {#if session.phase==='connected'}<p class="screen-sharing-blocked" role="alert">This existing session is blocked because its original canonical Sharing policy or active scene user changed. Restore access or disconnect; the remote desktop is not exposed.</p><button data-screen-sharing-control="blocked:disconnect" onclick={()=>command('disconnect')}>Disconnect Blocked Session</button>{/if}
 </main></div>
 {/if}
 </div>
 <footer class="screen-sharing-status" role="status"><span>{message||session.status}</span>{#if resultFile}<strong>Local File: {resultFile.name}</strong>{/if}<span>{connected?`${session.connectionType==='high-performance'?'High Performance · local virtual displays':'Standard'} · ${session.mode}`:'No connection'}</span></footer>
 {#if session.phase==='authentication'}<div class="screen-sharing-backdrop"><form class="screen-sharing-sheet screen-sharing-auth" onsubmit={event=>{event.preventDefault();signIn();}}><svg viewBox="0 0 48 48" aria-hidden="true"><rect x="5" y="7" width="38" height="27" rx="3"/><path d="M15 41h18M24 34v7"/></svg><h2>Connect to {receiver?.name}</h2><p>Sign in as the authored receiver user.</p><label>Name <input data-screen-sharing-control="auth:username" autocomplete="off" maxlength="64" bind:value={username}/></label><label>Fictional password <input data-screen-sharing-control="auth:passcode" type="password" autocomplete="off" maxlength="128" bind:value={passcode}/></label><div class="screen-sharing-auth-cue"><strong>Authored local credentials</strong><code>{receiver?.account} / {receiver?.passcode}</code><p>These are disclosed fiction. Never enter real credentials. No account lookup or network authentication occurs.</p></div><label class="screen-sharing-checkbox"><input data-screen-sharing-control="auth:remember" type="checkbox" bind:checked={remember}/> Remember authentication in this running app only</label><p class="screen-sharing-inline-error" role="status">{message}</p><footer><button data-screen-sharing-control="auth:cancel" type="button" onclick={()=>{passcode='';command('cancel');}}>Cancel</button><button data-screen-sharing-control="auth:signin" type="submit" class="primary" disabled={!username||!passcode}>Sign In</button></footer></form></div>{/if}
 {#if session.sheet}<div class="screen-sharing-backdrop"><section class="screen-sharing-sheet" role="dialog" aria-modal="true" aria-label={session.sheet==='help'?'Screen Sharing Help':session.sheet==='connection'?'New Connection':cap.settingsLabel}>
 {#if session.sheet==='connection'}<h2>{cap.windows?'Remote Desktop Connection · local':'New Connection'}</h2><p>{cap.classic?'Enter a computer name or VNC address.':'Enter a hostname or Apple ID in the native app. This local counterpart only accepts the authored names below.'}</p><label>{cap.windows?'Computer':'Hostname'} <input data-screen-sharing-control="connection:hostname" autocomplete="off" maxlength="256" bind:value={hostname} placeholder="studio.authored.local"/></label><div class="screen-sharing-auth-cue">{#each SCREEN_SHARING_RECEIVERS as row}<button data-screen-sharing-control={`hostname:${row.id}`} onclick={()=>{hostname=row.hostname;}}>{row.hostname}</button>{/each}<p>No DNS, VNC, RDP or Apple Account request is made.</p></div><footer><button data-screen-sharing-control="connection:cancel" onclick={()=>command('sheet',{sheet:null})}>Cancel</button><button data-screen-sharing-control="connection:connect" class="primary" disabled={!hostname||!access.enabled||!access.allowed} onclick={()=>{username='';passcode='';command('connect',{hostname});}}>Connect</button></footer>
 {:else if session.sheet==='settings'}<h2>{cap.classic?'Screen Sharing Preferences':cap.windows?'Local Remote Desktop Options':'Screen Sharing Settings'}</h2><fieldset><legend>Display</legend><label>Scale <select data-screen-sharing-control="settings:scale" value={session.scale} onchange={event=>command('settings',{scale:event.currentTarget.value})}><option value="fit">Scale to fit available space</option><option value="actual">Show full size</option></select></label><label>Zoom <select data-screen-sharing-control="settings:zoom" value={session.zoom} onchange={event=>command('settings',{zoom:Number(event.currentTarget.value)})}>{#each [50,75,100,125,150,175,200] as size}<option value={size}>{size}%</option>{/each}</select></label><label>Quality <select data-screen-sharing-control="settings:quality" value={session.quality} disabled={session.connectionType==='high-performance'} onchange={event=>command('settings',{quality:event.currentTarget.value})}><option value="adaptive">Adapt quality · genuine half-resolution rendering</option><option value="full">Show the screen at full quality</option></select></label>{#if cap.highPerformance&&receiver?.highPerformance}<label>Screen sharing type <select data-screen-sharing-control="settings:type" value={session.connectionType} onchange={event=>command('settings',{connectionType:event.currentTarget.value})}><option value="standard">Standard</option><option value="high-performance">High Performance · authored virtual displays</option></select></label>{#if session.connectionType==='high-performance'}<label>Virtual displays <select data-screen-sharing-control="settings:displays" value={session.displays} onchange={event=>command('settings',{displays:Number(event.currentTarget.value)})}><option value="1">One virtual display</option><option value="2">Two virtual displays</option></select></label><label class="screen-sharing-checkbox"><input data-screen-sharing-control="settings:dynamic" type="checkbox" checked={session.dynamicResolution} disabled={session.displays!==1} onchange={event=>command('settings',{dynamicResolution:event.currentTarget.checked})}/> Dynamic resolution · match the actual viewport</label><p>These are local canvases, not an Apple silicon stream. HDR / HEVC transport is not claimed.</p>{/if}{/if}</fieldset>
 <fieldset><legend>Canonical Sharing policy</legend><p><strong>{access.enabled?'On':'Off'}</strong> · {access.userName||'No actual user'} · {access.allowed?'allowed':'not allowed'}</p><p>These values are the same original Preferences service and allowed-user list. Actual administrator authorization is required.</p><label>Administrator <select data-screen-sharing-control="policy:administrator" value={administratorId||administrators[0]?.id||''} onchange={event=>{administratorId=event.currentTarget.value;}}>{#each administrators as row}<option value={row.id}>{row.name}</option>{/each}</select></label><label>Fictional scene passcode <input data-screen-sharing-control="policy:passcode" type="password" autocomplete="off" maxlength="128" bind:value={administratorPasscode}/></label><small>Initial authored scene passcode: <code>scene</code>. If changed in Preferences, use that fictional passcode. Never use a real password.</small><button data-screen-sharing-control="policy:authorize" disabled={!administrators.length||!administratorPasscode} onclick={authorize}>Authorize Sharing for Active User</button></fieldset><p class="screen-sharing-inline-error" role="status">{message}</p><footer><button data-screen-sharing-control="settings:done" class="primary" onclick={()=>{administratorPasscode='';command('sheet',{sheet:null});}}>Done</button></footer>
 {:else}<h2>{cap.label}</h2><p>{cap.disclosure}</p><p>{cap.qualification}</p><dl><dt>Functional desktop</dt><dd>Open, move, edit, save and close actual peer windows. Observe mode blocks mutation. Each receiver owns one bounded desktop and File graph shared by its session windows.</dd><dt>Genuine transfers</dt><dd>Sending reads original canonical File bytes. Receiving atomically creates a canonical File with its real MIME and content. Capture encodes the actual mounted virtual desktop canvas, not an image placeholder.</dd><dt>Authentication</dt><dd>Receiver credentials are openly authored fiction. Remembered authentication lives only in this running app and is discarded on quit or restored sessions.</dd><dt>Sharing</dt><dd>Local receiver access follows canonical Preferences and the actual active user's permission. No copied policy or Contacts graph is used.</dd></dl><footer><button data-screen-sharing-control="help:done" class="primary" onclick={()=>command('sheet',{sheet:null})}>Done</button></footer>{/if}
 </section></div>{/if}
 {:else}<p role="alert">The original Screen Sharing session is unavailable.</p>{/if}
</section>
